#include "titan_ftp_service.h"
#include "titan_network_stream.h"
#include "titan_storage_io.h"
#include "titan_network.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
static const char *cmds[]={"USER a\r\n","PASS b\r\n","EPSV\r\n","STOR upload.bin\r\n","EPSV\r\n","RETR download.bin\r\n","QUIT\r\n"};static unsigned ci;static int ctrl_acc,data_acc;static int current_data_session;static unsigned char uploaded[64];static unsigned uploaded_n;static const unsigned char incoming[]={1,2,3,4,5};static int incoming_phase;static const unsigned char download[]={9,8,7,6};static unsigned download_off;static unsigned char sent_data[64];static unsigned sent_n;static char replies[2048];static unsigned reply_n;static int open_mode;static char opened_path[256];static int published;static TitanNetworkStatus ns;
int TitanNetworkStream_Listen(TitanNetworkStreamOwner o,unsigned short p,unsigned int b,TitanNetworkStreamHandle*out){(void)b;assert(o==TITAN_NETWORK_STREAM_OWNER_FTP);*out=(p==2121)?1u:3u;data_acc=0;return 1;}
int TitanNetworkStream_Accept(TitanNetworkStreamHandle l,unsigned int d,TitanNetworkStreamHandle*out){assert(d==1u);if(l==1u){if(ctrl_acc)return 0;ctrl_acc=1;*out=2;return 1;}if(l==3u){if(data_acc)return 0;data_acc=1;current_data_session++;*out=4;return 1;}return 0;}
int TitanNetworkStream_Read(TitanNetworkStreamHandle s,void*b,unsigned int cap,unsigned int d,unsigned int*out){const char*c;unsigned n;assert(s==2&&d==1);if(ci>=sizeof(cmds)/sizeof(cmds[0])){*out=0;return 0;}c=cmds[ci++];n=strlen(c);assert(n<=cap);memcpy(b,c,n);*out=n;return 1;}
TitanNetworkStreamIoStatus TitanNetworkStream_ReadStatus(TitanNetworkStreamHandle s,void*b,unsigned int cap,unsigned int d,unsigned int*out){assert(s==4&&d==1);if(current_data_session!=1)return TITAN_NETWORK_STREAM_IO_ERROR;if(incoming_phase==0){assert(sizeof(incoming)<=cap);memcpy(b,incoming,sizeof(incoming));*out=sizeof(incoming);incoming_phase=1;return TITAN_NETWORK_STREAM_IO_DATA;}*out=0;return TITAN_NETWORK_STREAM_IO_CLOSED;}
int TitanNetworkStream_Write(TitanNetworkStreamHandle s,const void*b,unsigned int n,unsigned int d,unsigned int*out){assert(d==1000);if(s==2){memcpy(replies+reply_n,b,n);reply_n+=n;replies[reply_n]=0;}else{assert(s==4);memcpy(sent_data+sent_n,b,n);sent_n+=n;}*out=n;return 1;}
void TitanNetworkStream_Close(TitanNetworkStreamHandle h){(void)h;}void TitanNetworkStream_CancelOwner(TitanNetworkStreamOwner o){(void)o;}const TitanNetworkStatus*TitanNetwork_GetStatus(void){strcpy(ns.ip,"10.0.0.2");return &ns;}
int TitanStorageIo_PathInfo64(const char*p,int*d,TitanStorageIoSize*z){(void)p;*d=1;*z=0;return 1;}int TitanStorageIo_ListDirectory(const char*p,unsigned int i,TitanStorageIoEntry*e,unsigned int c){(void)p;(void)i;(void)e;(void)c;return 0;}
int TitanStorageIo_Open(const char*p,int flags){strcpy(opened_path,p);open_mode=flags;if(strstr(p,"upload.bin.titantmp"))return 20;if(strstr(p,"download.bin"))return 21;return -1;}int TitanStorageIo_Close(int fd){assert(fd==20||fd==21);return 1;}int TitanStorageIo_WriteExact(int fd,const void*b,size_t n){assert(fd==20);memcpy(uploaded+uploaded_n,b,n);uploaded_n+=n;return 1;}TitanStorageIoResult TitanStorageIo_ReadSome(int fd,void*b,size_t n){unsigned left,take;assert(fd==21);left=sizeof(download)-download_off;if(!left)return 0;take=left<n?left:n;memcpy(b,download+download_off,take);download_off+=take;return take;}int TitanStorageIo_AtomicReplace(const char*t,const char*d,const char*bak){assert(bak==0);assert(strcmp(t,"mass:/upload.bin.titantmp")==0);assert(strcmp(d,"mass:/upload.bin")==0);published=1;return 1;}int TitanStorageIo_RemoveAny(const char*p){(void)p;return 1;}
int main(void){unsigned i;assert(TitanFtpService_Start("mass:/",2121));for(i=0;i<50;i++)TitanFtpService_Tick();assert(uploaded_n==sizeof(incoming)&&memcmp(uploaded,incoming,sizeof(incoming))==0);assert(published);assert(sent_n==sizeof(download)&&memcmp(sent_data,download,sizeof(download))==0);assert(strstr(replies,"226 File upload committed")!=0);assert(strstr(replies,"226 File transfer complete")!=0);TitanFtpService_Stop();puts("buildfix27-ftp-file-host: OK RETR + transactional STOR");return 0;}
